INSERT INTO feature VALUES('glf-model-in-source','theory','A model of a signature written in source; the shape parameter','glf-two-views','partial','unique','dependent provers','A first-order model of a signature is written as a record type in source — Model(Nat) as #{nat : Type, zero : () => nat, succ : (n : nat) => nat}, its syntax model inhabiting it, the module packed into it — and a theory block states the finite shape its cells are over (boundary Square { tl, tr, bl, br }; face left = { tl, bl };), a face refused holding a name the boundary lacks or repeated; the λ-calculus single-substitution model as a record waits on gandr #721, its syntax model (two laws by induction on a neutral) the next unit.','theory-levitation','corpus/model/desc/model-in-source.gandr','corpus/ledger/features/glf-model-in-source.gandr','#640');
